def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Each small pattern is a 2-colored diamond: two rows of three cells
    # [outer 2, center 0, outer 2] / [center 2, outer 0, center 2] etc.
    # For each pair of side-by-side diamonds, connect facing horizontal tips;
    # then the central diamond's column continues downward through the gap.
    # Detect individual 5-cell diamond motifs.
    motifs=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if (grid[r-1][c]==2 and grid[r][c-1]==2 and grid[r][c+1]==2 and grid[r+1][c]==2):
                motifs.append((r,c))
    # Connect adjacent diamond motifs on the same middle row, and extend down
    # from the last motif if its central column is vertically aligned.
    for r,c in motifs:
        for rr,cc in motifs:
            if rr==r and cc>c+2 and cc-c>=4:
                for x in range(c+2,cc-1):
                    if grid[r][x]==0: out[r][x]=1
    # General ray from an isolated centered 2 down to the next 2 in same column.
    for r,c in motifs:
        for rr in range(r+1,h):
            if grid[rr][c]==2:
                for y in range(r+1,rr):
                    if grid[y][c]==0: out[y][c]=1
                break
    return out
