    # Match the demonstrated composite: 3 diamond-like motifs arranged in a
    # row, with intervening horizontal gaps, and a lower central vertical line.
    # A diamond center has all four cardinal neighbors colored 2.
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r-1][c]==2 and grid[r+1][c]==2 and grid[r][c-1]==2 and grid[r][c+1]==2:
                centers.append((r,c))
    # The training motifs are imperfect (one arm may be offset); identify
    # center of a 3-2-3 chevron from a horizontal pair with vertical 2 support.
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c-1]==2 and grid[r][c+1]==2 and grid[r-1][c]==2 and grid[r+1][c]==2:
                centers.append((r,c))
    centers=sorted(set(centers))
    # Connect gaps between repeated motif centers on same row.
    for r in range(h):
        cs=sorted(c for rr,c in centers if rr==r)
        for a,b in zip(cs,cs[1:]):
