                if c>0 and d+1<w and grid[r-1][c-1]==2 and grid[r+1][c-1]==2 and grid[r-1][d+1]==2 and grid[r+1][d+1]==2:
                    for x in range(c+1,d):
                        if grid[r][x]==0: out[r][x]=1
                    break
    # Vertical connector: add 1s between a centered top 2 with horizontal 2s
    # and a later aligned 2, but only when an intervening pattern indicates a stem.
    for c in range(1,w-1):
        for r in range(1,h):
            if grid[r][c]==2 and grid[r-1][c-1]==2 and grid[r-1][c+1]==2:
                # nearest subsequent 2 in column is the endpoint
                end=next((rr for rr in range(r+1,h) if grid[rr][c]==2),None)
