def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Horizontal strings join the two inward-facing ends of neighboring
    # chevrons. Endpoints are the 2s in the middle row, with diagonal 2 arms
    # immediately outside the gap on the row above (as in all demos).
    for r in range(1, h):
        cols = [c for c, v in enumerate(grid[r]) if v == 2]
        for a, b in zip(cols, cols[1:]):
            if b - a < 3 or a == 0 or b + 1 >= w:
                continue
            if grid[r-1][a-1] == 2 and grid[r-1][b+1] == 2:
                for c in range(a+1, b):
                    if grid[r][c] == 0:
                        out[r][c] = 1
    # Vertical strings connect matching 2 endpoints separated by two empty
    # rows, when the endpoints are side tips of repeated bowtie motifs.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 2]
        for a, b in zip(rows, rows[1:]):
            if b-a != 3:
                continue
            # A side tip is evidenced by a second 2 on its row at distance two.
            side_tip = any((0 <= c+d < w and grid[a][c+d] == 2) or
                           (0 <= c+d < w and grid[b][c+d] == 2) for d in (-2, 2))
            if side_tip:
                for r in range(a+1, b):
                    if grid[r][c] == 0:
                        out[r][c] = 1
    return out
