def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    # A motif is a diamond of four 2s surrounding an empty center.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r-1][c] == 2 and grid[r+1][c] == 2
                    and grid[r][c-1] == 2 and grid[r][c+1] == 2):
                centers.append((r, c))
    # Connect neighboring diamonds along their common axis, leaving one cell
    # of each diamond's outline at either end of the colored bridge.
    for r in range(h):
        cs = sorted(c for rr, c in centers if rr == r)
        for a, b in zip(cs, cs[1:]):
            for c in range(a + 2, b - 1):
                if grid[r][c] == 0:
                    out[r][c] = 1
    for c in range(w):
        rs = sorted(r for r, cc in centers if cc == c)
        for a, b in zip(rs, rs[1:]):
            for r in range(a + 2, b - 1):
                if grid[r][c] == 0:
                    out[r][c] = 1
    return out
