def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Locate motif midpoints: three adjacent 2s in a row form two touching
    # chevrons; fill the interior horizontal run where the row is enclosed by
    # corresponding 2 arms on the row above/below.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and grid[r][c-1] == 2 and grid[r][c+1] == 2:
                if grid[r-1][c-1] == 2 and grid[r+1][c+1] == 2:
                    out[r][c] = 2
    # Main horizontal bridge is the only gap bounded by matching 2 endpoints
    # with diagonal neighbors, between the adjacent chevrons.
    for r in range(h):
        cols=[c for c,v in enumerate(grid[r]) if v==2]
        for a,b in zip(cols,cols[1:]):
            if b-a<3: continue
            if r>0 and r+1<h and a>0 and b+1<w:
                if grid[r-1][a-1]==2 and grid[r+1][a-1]==2 and grid[r-1][b+1]==2 and grid[r+1][b+1]==2:
                    for c in range(a+1,b):
                        if grid[r][c]==0: out[r][c]=1
    # Vertical bridges between repeated side tips with matching diagonal support.
    for c in range(1,w-1):
        rows=[r for r in range(h) if grid[r][c]==2]
        for a,b in zip(rows,rows[1:]):
            if b-a!=3: continue
            for r0 in (a-1,a+1,b-1,b+1):
                if 0<=r0<h and grid[r0][c-1]==2 and grid[r0][c+1]==2:
                    for r in range(a+1,b):
                        if grid[r][c]==0: out[r][c]=1
                    break
    return out
