def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # Detect complete bowtie motifs: a three-row shape with two outer tips
    # at the middle row and the matching inward-facing 2s above/below.
    motifs=[]
    for r in range(1,h-1):
        for a in range(w-2):
            b=a+2
            if (grid[r][a]==2 and grid[r][b]==2 and
                grid[r-1][a+1]==2 and grid[r+1][a+1]==2):
                motifs.append((r,a,b))
    # Connect consecutive bowtie units in a row by filling the entire open
    # horizontal gap between their inner tips.
    for r,a,b in motifs:
        for rr,d,e in motifs:
            if rr==r and d>b+1:
                for c in range(b+1,d):
                    if grid[r][c]==0: out[r][c]=1
    # For stacked motifs, join their aligned side tips across an empty vertical
    # gap. A side tip is a 2 endpoint with an adjacent same-row 2 at distance 2.
    tips={}
    for r,a,b in motifs:
        tips.setdefault(a,[]).append(r)
        tips.setdefault(b,[]).append(r)
    for c,rs in tips.items():
        rs=sorted(set(rs))
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==0: out[r][c]=1
    return out
